import { useSuspenseQuery } from "@tanstack/react-query"
import Browser from "webextension-polyfill"
import { CURRENT_ORG_ID_COOKIE, getCurrentOrgIdFromCookies } from "../sidepanel/lib/browser"

export const processCookieStr = (cookiesStr: string, prefix: string) => {
	const cookieStrList = cookiesStr.split("; ")
	const newStrList = []

	for (const cookieStr of cookieStrList) {
		if (cookieStr.startsWith(prefix)) {
			newStrList.push(cookieStr.substring(prefix.length, cookieStr.length))
		}
	}
	return newStrList.join("; ")
}

export const processSetCookieStr = (str: string, prefix: string) => {
	const cookieStrList = str.split("\n")
	const newStrList = []

	for (const setCookie of cookieStrList) {
		newStrList.push(`${prefix}${setCookie}`)
	}
	return newStrList.join("\n")
}

export function useSuspenseCurrentOrgId() {
	return useSuspenseQuery({
		queryKey: [CURRENT_ORG_ID_COOKIE],
		queryFn: () => getCurrentOrgIdFromCookies(),
	})
}

export const getCookies = () => Browser.cookies.getAll({})

export function findCookie(
	cookies: Browser.Cookies.Cookie[],
	name: string,
	domainMatch?: string | ((domain: string) => boolean),
) {
	return cookies.find((cookie) => {
		const domainMatches =
			typeof domainMatch === "function"
				? domainMatch(cookie.domain)
				: domainMatch
					? cookie.domain.includes(domainMatch)
					: true
		return cookie.name === name && domainMatches
	})
}
