import { useEffect } from "react"
import type { UpdateTabMessage } from "src/shared/messages"
import Browser from "webextension-polyfill"
import { findCookie, getCookies } from "../../shared/cookies"
import { getPhantombusterDomain } from "../../shared/helpers"
import { redirectUri } from "./crm"
import { useQueryClient, useSuspenseQuery } from "@tanstack/react-query"

/**
 *
 * INFO
 *
 */

export function getExtensionVersion() {
	return Browser.runtime.getManifest().version
}

export function getBrowserName(): "chrome" | "edge" | "firefox" {
	if (navigator.userAgent.includes("Edg/")) return "edge"
	if (navigator.userAgent.includes("Firefox/")) return "firefox"
	return "chrome" // Default to Chrome (covers Chrome and Chromium-based browsers)
}

/**
 *
 * COOKIES
 *
 */

export const CURRENT_ORG_ID_COOKIE = "pb:currentOrgId"

export async function getCsrfToken() {
	const cookies = await getCookies()
	const jsession = findCookie(cookies, "JSESSIONID")
	return jsession?.value.replace(/"/g, "") ?? ""
}

export async function getSessionCookies() {
	const cookies = await getCookies()
	const domain = getPhantombusterDomain()

	const session = findCookie(cookies, "session", domain)
	const sessionUser = findCookie(cookies, "hjSessionUser", domain)

	return `${sessionUser?.name}=${sessionUser?.value}; ${session?.name}=${session?.value}`
}

export async function getLinkedinSession() {
	const cookies = await getCookies()
	return findCookie(cookies, "li_at")?.value
}

export async function getCurrentOrgIdFromCookies() {
	const cookies = await getCookies()
	const baseDomain = new URL(import.meta.env.VITE_PHANTOMBUSTER_BASE_URL).hostname

	const currentOrg = findCookie(cookies, CURRENT_ORG_ID_COOKIE, baseDomain)

	return currentOrg?.value ?? ""
}

/**
 *
 * TABS
 *
 */

export async function getActiveTab() {
	const [tab] = await Browser.tabs.query({ active: true, lastFocusedWindow: true })
	return tab
}

export function onActiveTabChange(callback: (tab: Browser.Tabs.Tab) => unknown) {
	Browser.tabs.onActivated.addListener(async () => {
		const tab = await getActiveTab()
		callback(tab)
	})
}

/** Checks if the current tab is in a different browser window */
const isTabInDifferentWindow = async (windowId?: number) => {
	const { id } = await Browser.windows.getCurrent()

	return windowId !== id
}

/** Checks if a new tab is opened via a link but doesn't change the current tab
 * {@link https://phantombuster.atlassian.net/browse/PIX-221}
 */
const isLinkOpenedInNewTab = async (newTabId: number) => {
	const currentTab = await getActiveTab()
	return currentTab.id !== newTabId
}

export function onActiveTabUpdate(callback: (tab: Browser.Tabs.Tab) => unknown) {
	Browser.tabs.onUpdated.addListener(async (tabId, _changeInfo, tab) => {
		// Prevents the sidepanel to change state when manipulating another browser window
		if (await isTabInDifferentWindow(tab.windowId)) return
		// Prevents the sidepanel to change state when opening a link in a new tab
		if (await isLinkOpenedInNewTab(tabId)) return

		// Prevents the sidepanel to change state when manipulating another browser window
		callback(tab)
	})
}

export function useSuspenseTab() {
	const queryClient = useQueryClient()

	useEffect(() => {
		function setTab(tab: Browser.Tabs.Tab) {
			queryClient.setQueryData(["tab"], tab)
		}
		onActiveTabUpdate(setTab)
		onActiveTabChange(setTab)
	}, [])

	return useSuspenseQuery({
		queryKey: ["tab"],
		queryFn: getActiveTab,
	})
}

/**
 * Sends a message to background.ts script to update the tab current URL
 */
export const updateTabUrl = (message: UpdateTabMessage) => Browser.runtime.sendMessage(message)

export async function openAuthInNewTabAndCloseWhenDone(authUrl: string, pollingMs: number = 1000) {
	const tab = await Browser.tabs.create({ url: authUrl, active: true })
	if (!tab.id) return

	const pollInterval = setInterval(async () => {
		if (!tab.id) return
		try {
			const updatedTab = await Browser.tabs.get(tab.id)

			if (updatedTab.url?.startsWith(redirectUri) && updatedTab.status === "complete") {
				clearInterval(pollInterval)
				await Browser.tabs.remove(tab.id)
			}
		} catch (err) {
			// Ignore errors (tab may be closed or not accessible)
			console.error("Polling tab error:", err)
		}
	}, pollingMs)
}
