import { useSuspenseUser } from "~/lib/users"

export function LoggedAsBanner() {
	const { data: user } = useSuspenseUser()
	if (!user || !user.isLoggedAs) {
		return null
	}
	return (
		<div className="absolute top-0 w-full bg-success/50 text-center text-foreground">
			Logged as {user.firstName} {user.lastName}
		</div>
	)
}
