import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import localforage from "localforage"

export const phantombusterStore = localforage.createInstance({
	name: "PhantomBuster",
})

export const LOCAL_PROFILE_KEY = "phantombusterLocalProfile"

export const DISCOVERY_HISTORY_KEY = "phantombusterDiscoveryHistory"

export interface ILocalProfile {
	slug: string
	email?: string
	phone?: string
	isAddedToOutreach?: boolean
	isEmailDiscoveryPerformed?: boolean
	discoveryDate?: Date
}

export function useLocalProfile(profileSlug: string) {
	return useQuery({
		queryKey: [LOCAL_PROFILE_KEY, profileSlug],
		queryFn: async () => {
			if (!profileSlug) return null
			return phantombusterStore.getItem<ILocalProfile>(profileSlug)
		},
	})
}

export function useDiscoveryHistory() {
	return useQuery({
		queryKey: [DISCOVERY_HISTORY_KEY],
		queryFn: async () => {
			const keys = await phantombusterStore.keys()
			const allItems = await Promise.all(keys.map((key) => phantombusterStore.getItem(key)))

			const discoveredItems = (allItems as ILocalProfile[])
				.filter(
					(item) =>
						typeof item === "object" &&
						item &&
						"isEmailDiscoveryPerformed" in item &&
						item?.isEmailDiscoveryPerformed,
				)
				.sort((a, b) => (b.discoveryDate?.getTime() ?? 0) - (a.discoveryDate?.getTime() ?? 0))

			return discoveredItems
		},
	})
}

export function useMutationLocalProfile() {
	const queryClient = useQueryClient()

	return useMutation({
		mutationFn: async (args: { profileSlug: string; data: Partial<ILocalProfile> }) => {
			const { profileSlug, data } = args
			const localProfile = await phantombusterStore.getItem<ILocalProfile>(profileSlug)
			return phantombusterStore.setItem(profileSlug, {
				...(localProfile ?? { slug: profileSlug }),
				...data,
				discoveryDate: new Date(),
			})
		},
		onSuccess: async (_, { profileSlug }) => {
			await queryClient.refetchQueries({ queryKey: [LOCAL_PROFILE_KEY, profileSlug] })
		},
	})
}
