import { QueryClient } from "@tanstack/react-query"
import { PersistedClient, Persister, PersistQueryClientProvider } from "@tanstack/react-query-persist-client"
import { phantombusterStore } from "../lib/indexed-db"

const queryClient = new QueryClient()

/**
 * Creates an Indexed DB persister
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IndexedDB_API
 */
function createIDBPersister(idbValidKey: string) {
	return {
		persistClient: async (client: PersistedClient) => {
			await phantombusterStore.setItem(idbValidKey, JSON.stringify(client))
		},
		restoreClient: async () => {
			try {
				const client = await phantombusterStore.getItem<string>(idbValidKey)
				return client ? (JSON.parse(client) as PersistedClient) : undefined
			} catch (error) {
				console.error(error)
				return
			}
		},
		removeClient: async () => {
			await phantombusterStore.removeItem(idbValidKey)
		},
	} satisfies Persister
}

export function ReactQueryProvider({ children }: { children: React.ReactNode }) {
	return (
		<PersistQueryClientProvider
			client={queryClient}
			persistOptions={{
				persister: createIDBPersister("react-query"),
			}}
		>
			{children}
		</PersistQueryClientProvider>
	)
}
