import { useSuspenseQuery } from "@tanstack/react-query"
import { fetchCurrentUser } from "../services/pbV2"
import { getCurrentOrgIdFromCookies } from "./browser"

// eslint-disable-next-line @typescript-eslint/naming-convention
export const UsersQueryKey = {
	FetchMe: "/users/fetch-me",
} as const

export type UsersQueryKey = (typeof UsersQueryKey)[keyof typeof UsersQueryKey]

export function useSuspenseUser() {
	return useSuspenseQuery({
		queryKey: [UsersQueryKey.FetchMe],
		queryFn: async ({ signal }) => {
			const detailedOrgId = await getCurrentOrgIdFromCookies()
			return fetchCurrentUser(detailedOrgId ?? undefined, { signal })
		},
		select: (res) => res.data?.user ?? null,
	})
}
