/* eslint-disable @typescript-eslint/naming-convention */
import { lazy, useEffect } from "react"
import { BrowserRouter, MemoryRouter, Route, Routes } from "react-router"
import { LoggedAsBanner } from "./components/LoggesAsBanner"
import { useSuspenseTab } from "./lib/browser"
import { useSuspenseUser } from "./lib/users"
import type { paths } from "./types/pb-v2"

const ValidateEmailRoute = lazy(() => import("./routes/ValidateEmailRoute"))
const HubSpotOAuthRoute = lazy(() => import("./routes/HubSpotOAuthRoute"))
const UpgradePlan = lazy(() => import("./routes/UpgradePlanRoute"))
const UnprocessedResourceRoute = lazy(() => import("./routes/UnprocessedResourceRoute"))
const LinkedinProfileRoute = lazy(() => import("./routes/LinkedinProfileRoute"))
const LoginRoute = lazy(() => import("./routes/LoginRoute"))
const LinkedinSearchExportRoute = lazy(() => import("./routes/LinkedinSearchExportRoute"))
const ComingSoonRoute = lazy(() => import("./routes/ComingSoonRoute"))

function isPayingUser(
	user: paths["/users/fetch-me"]["get"]["responses"]["200"]["content"]["application/json"]["user"],
): boolean {
	const plan = user?.detailedOrg?.plan
	return (
		(plan?.monthlyPrice !== undefined && plan.monthlyPrice !== 0) ||
		(plan?.yearlyPrice !== undefined && plan.yearlyPrice !== 0) ||
		(plan?.monthlyPrices !== undefined && Object.values(plan.monthlyPrices).some((price) => price !== 0)) ||
		(plan?.yearlyPrices !== undefined && Object.values(plan.yearlyPrices).some((price) => price !== 0))
	)
}

export function App() {
	const user = useSuspenseUser()
	const { data: tab } = useSuspenseTab()
	const tabUrl = tab?.url ? `/${tab.url}` : ""

	useEffect(() => {
		void user.refetch()
	}, [tabUrl])

	if (user.isLoading) return null

	if (!user.data) {
		return (
			<MemoryRouter initialEntries={["/login"]}>
				<Routes>
					<Route path="/login" element={<LoginRoute />} />
				</Routes>
			</MemoryRouter>
		)
	}

	if (!isPayingUser(user.data)) {
		return (
			<MemoryRouter initialEntries={["/coming-soon"]}>
				<Routes>
					<Route path="/coming-soon" element={<ComingSoonRoute />} />
				</Routes>
			</MemoryRouter>
		)
	}

	if (!user.data.isEmailValidated) {
		return (
			<MemoryRouter initialEntries={[`/validate-email/${user.data.email}`]}>
				<Routes>
					<Route path="/validate-email/:email" element={<ValidateEmailRoute />} />
				</Routes>
			</MemoryRouter>
		)
	}

	return (
		<>
			<LoggedAsBanner />
			<BrowserRouter>
				<Routes location={tabUrl}>
					<Route path="/">
						<Route path="upgrade-plan" element={<UpgradePlan />} />
						<Route path="https://www.linkedin.com/in/:slug/*" element={<LinkedinProfileRoute />} />
						<Route path="https://app.hubspot.com/oauth/authorize/*" element={<HubSpotOAuthRoute />} />
						<Route path="https://app.hubspot.com/oauth-bridge" element={<HubSpotOAuthRoute />} />
						<Route path="https://app-eu1.hubspot.com/oauth/*" element={<HubSpotOAuthRoute />} />
						<Route
							path="https://www.linkedin.com/search/results/:type/*"
							element={<LinkedinSearchExportRoute />}
						/>
						<Route path="https://www.linkedin.com/jobs/search/*" element={<LinkedinSearchExportRoute />} />
						<Route
							path={new URL(
								"/auth-callback/hubspot",
								import.meta.env.VITE_PHANTOMBUSTER_BASE_URL,
							).toString()}
							element={<HubSpotOAuthRoute />}
						/>
						<Route path="*" element={<UnprocessedResourceRoute />} />
					</Route>
				</Routes>
			</BrowserRouter>
		</>
	)
}
