import createClient, { Middleware } from "openapi-fetch"
import {
	getBrowserName,
	getCurrentOrgIdFromCookies,
	getExtensionVersion,
	openAuthInNewTabAndCloseWhenDone,
} from "../lib/browser"
import { getHubspotOAuthUrl } from "../lib/crm"
import type {
	AddLeadToListPayload,
	LeadsListResponse,
	SaveLeadsPayload,
	SearchLeadPayload,
	SearchLeadProps,
	SearchLeadResponse,
} from "../types/leads"
import type { paths } from "../types/pb-v2"

export const apiV2Client = createClient<paths>({
	baseUrl: new URL("/api/v2", import.meta.env.VITE_PHANTOMBUSTER_API_URL).toString(),
	headers: {
		"x-phantombuster-browser-extension": getBrowserName(),
		"x-phantombuster-browser-extension-version": getExtensionVersion(),
	},
})

const middleware: Middleware = {
	async onRequest({ request }) {
		const orgIdHeader = "X-Phantombuster-Org"

		const currentOrgId = await getCurrentOrgIdFromCookies()
		const hasOrgIdHeader = request.headers.has(orgIdHeader)
		const shouldReplaceOrgIdHeader = !hasOrgIdHeader && currentOrgId

		if (shouldReplaceOrgIdHeader) {
			request.headers.set(orgIdHeader, currentOrgId)
		}

		if (import.meta.env.MODE === "development") {
			// eslint-disable-next-line no-console
			console.info(`[ApiPbV2Client] Making ${request.method} request to: ${request.url}`)
			// eslint-disable-next-line no-console
			console.info(`[ApiPbV2Client] Headers:`, Object.fromEntries(request.headers))
		}

		return request
	},
}

apiV2Client.use(middleware)

/**
 * USERS SERVICES
 */

export const fetchCurrentUser = (detailedOrgId?: string, init?: RequestInit) =>
	apiV2Client.GET("/users/fetch-me", {
		params: detailedOrgId
			? {
					query: {
						detailedOrgId,
					},
				}
			: undefined,
		signal: init?.signal,
	})

/**
 * AGENTS SERVICES
 */

type OpenApiResult = {
	error?: { error: string; status: "error" }
	response: { status: number }
}

type SaveAgentBody = NonNullable<paths["/agents/save"]["post"]["requestBody"]>["content"]["application/json"]
type SaveAgentResponseData = NonNullable<
	paths["/agents/save"]["post"]["responses"]
>["200"]["content"]["application/json"]

export const saveAgent = async (
	body: SaveAgentBody,
): Promise<
	OpenApiResult & {
		data?: SaveAgentResponseData
	}
> =>
	apiV2Client.POST("/agents/save", {
		body,
	})

type LaunchAgentResponseData = NonNullable<paths["/agents/launch"]["post"]["responses"]>["200"]["content"]

export const launchAgent = async ({
	agentId,
}: {
	agentId: string
}): Promise<
	OpenApiResult & {
		data?: LaunchAgentResponseData
	}
> =>
	apiV2Client.POST("/agents/launch", {
		body: { id: agentId },
	})

interface GetCurrentPhantomsQueryParams {
	inputTypes?: string[] | string
	outputTypes?: string[] | string
	agentIds?: string[] | string
	withAgentSlotsFactor?: string
	withArgument?: string
}

export type CurrentPhantomsResponse =
	paths["/agents/fetch-all"]["get"]["responses"]["200"]["content"]["application/json"]

export async function getCurrentPhantoms(queryParams: GetCurrentPhantomsQueryParams = {}) {
	return apiV2Client.GET("/agents/fetch-all", {
		params: { query: queryParams },
	})
}

/**
 * ORG STORAGE (LEADS & LISTS) SERVICES
 */

/** Upsert a lead */
export const saveLead = async (body: SaveLeadsPayload, init?: RequestInit) =>
	apiV2Client.POST("/org-storage/leads/save", {
		body,

		signal: init?.signal,
	})

/** Upsert a list */
export const saveList = async (body: AddLeadToListPayload, init?: RequestInit) =>
	apiV2Client.POST("/org-storage/lists/save", {
		body: Object(body),
		signal: init?.signal,
	})

export const searchLeadBySlug = async (
	{ slug }: SearchLeadProps,
	init?: RequestInit,
): Promise<{ data: SearchLeadResponse }> =>
	// @ts-expect-error - As the route is not exposed in the open-api spec, we need to manually set the types
	apiV2Client.POST("/org-storage/leads/search", {
		body: {
			automatedCall: false,
			paginationOptions: {
				paginationOffset: 0,
				paginationSize: 50,
				paginationProperty: "editions_history.-1.timestamp",
				paginationOrder: "DESC",
				includeTotalCount: true,
			},
			filter: {
				and: [
					{
						and: [
							{
								filter: {
									linkedin_profile_slug: {
										operator: "equals",
										valueToCompare: slug,
									},
								},
							},
						],
					},
				],
			},
		} satisfies SearchLeadPayload,
		signal: init?.signal,
	})

export const getListById = async (listId: string, init?: RequestInit) => {
	const res = await apiV2Client.GET("/org-storage/lists/fetch", {
		params: {
			query: { id: listId },
		},
		signal: init?.signal,
	})

	return res.data as unknown as LeadsListResponse
}
export const getLeadsLists = (init?: RequestInit) =>
	apiV2Client.GET("/org-storage/lists/fetch-all", {
		signal: init?.signal,
	})

/**
 * CRM SERVICES
 */

export type CreateContactBody = NonNullable<
	paths["/orgs/save-crm-contact"]["post"]["requestBody"]
>["content"]["application/json"]

export async function createCrmContact(body: CreateContactBody, init?: RequestInit) {
	const response = await apiV2Client.POST("/orgs/save-crm-contact", {
		body,
		signal: init?.signal,
	})
	return response
}

export async function fetchMyCrmResources(init?: RequestInit) {
	const response = await apiV2Client.GET("/orgs/fetch-crm-resources", {
		params: { query: { resourceType: "account_info" } },
		signal: init?.signal,
	})
	return response
}

export async function handleHSConnection(init?: RequestInit) {
	const { data: response } = (await apiV2Client.GET("/orgs/generate-crm-authenticity-token", {
		signal: init?.signal,
	})) as unknown as { data: { token?: string } }

	if (response?.token) {
		const authUrl = getHubspotOAuthUrl(response?.token)
		await openAuthInNewTabAndCloseWhenDone(authUrl)
	}
}

export interface PbV2Error {
	status: string
	error: string
	details?: Record<string, string>
}
