import { useMutation, useQuery } from "@tanstack/react-query"
import { toast } from "sonner"
import { createCrmContact, fetchMyCrmResources } from "../services/pbV2"
import { paths } from "../types/pb-v2"

export type GetMyCrmAccessResponse = Extract<
	NonNullable<paths["/orgs/fetch-crm-resources"]["get"]["responses"][200]["content"]["application/json"]>,
	{ resourceType: "account_info" }
>

export type SaveHubspotLeadPayload = NonNullable<
	paths["/orgs/save-crm-contact"]["post"]["requestBody"]
>["content"]["application/json"]

export function useFetchMyCrmResources() {
	return useQuery({
		queryKey: ["/orgs/fetch-crm-resources"],
		queryFn: ({ signal }) => fetchMyCrmResources({ signal }) as unknown as { data: GetMyCrmAccessResponse },
		select: (res) => res.data?.data ?? null,
	})
}

export function useMutationSaveHubspotLead() {
	return useMutation({
		mutationFn: async (args: { payload: SaveHubspotLeadPayload }) => createCrmContact(args.payload),
		onSuccess() {
			toast.success("Profile saved to HubSpot", { dismissible: true })
		},
	})
}

const clientId = "8dd9e15d-8974-40b7-a914-f433a9c6b354"

const scopes = [
	"timeline",
	"oauth",
	"crm.objects.contacts.read",
	"crm.objects.contacts.write",
	"crm.schemas.contacts.read",
	"crm.schemas.contacts.write",
	"crm.objects.companies.read",
	"crm.objects.companies.write",
	"crm.schemas.companies.read",
	"crm.schemas.companies.write",
	"crm.lists.read",
	"crm.lists.write",
].join(" ")

const baseUrl = new URL(import.meta.env.VITE_PHANTOMBUSTER_BASE_URL).toString()
export const redirectUri = new URL("/auth-callback/hubspot", baseUrl).toString()

export function getHubspotOAuthUrl(token: string): string {
	const url = new URL("https://app.hubspot.com/oauth/authorize")

	// app's client ID
	url.searchParams.append("client_id", clientId)
	// scopes being requested by the app
	url.searchParams.append("scope", scopes)
	// where to send the user after the consent page
	url.searchParams.append("redirect_uri", redirectUri)
	// token used to prevent CSRF vulnerability
	url.searchParams.append("state", token)

	return url.toString()
}
